package search

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strconv"
	"time"
)

const apiTimeout = 30 * time.Second

// DefaultServiceURL is the production search service URL.
const DefaultServiceURL = "https://entire.io"

// Meta contains search ranking metadata for a result.
type Meta struct {
	RRFScore   float64 `json:"rrfScore"`
	MatchType  string  `json:"matchType"`
	VectorRank *int    `json:"vectorRank"`
	BM25Rank   *int    `json:"bm25Rank"`
}

// Result represents a single search result from the search service.
type Result struct {
	CheckpointID         string      `json:"checkpointId"`
	Branch               string      `json:"branch"`
	CommitSHA            *string     `json:"commitSha"`
	CommitMessage        *string     `json:"commitMessage"`
	CommitAuthor         *string     `json:"commitAuthor"`
	CommitAuthorUsername *string     `json:"commitAuthorUsername"`
	CommitDate           *string     `json:"commitDate"`
	Additions            int         `json:"additions"`
	Deletions            int         `json:"deletions"`
	FilesChanged         int         `json:"filesChanged"`
	FilesTouched         []string    `json:"filesTouched"`
	FileStats            interface{} `json:"fileStats"`
	Prompt               *string     `json:"prompt"`
	Agent                string      `json:"agent"`
	Steps                int         `json:"steps"`
	SessionCount         int         `json:"sessionCount"`
	CreatedAt            string      `json:"createdAt"`
	InputTokens          *int        `json:"inputTokens"`
	OutputTokens         *int        `json:"outputTokens"`
	CacheCreationTokens  *int        `json:"cacheCreationTokens"`
	CacheReadTokens      *int        `json:"cacheReadTokens"`
	APICallCount         *int        `json:"apiCallCount"`
	Meta                 Meta        `json:"searchMeta"`
}

// Response is the search service response.
type Response struct {
	Results []Result `json:"results"`
	Query   string   `json:"query"`
	Repo    string   `json:"repo"`
	Total   int      `json:"total"`
	Error   string   `json:"error,omitempty"`
}

// Config holds the configuration for a search request.
type Config struct {
	ServiceURL  string // Base URL of the search service
	GitHubToken string
	Owner       string
	Repo        string
	Query       string
	Branch      string
	Limit       int
}

// Search calls the search service to perform a hybrid search.
func Search(ctx context.Context, cfg Config) (*Response, error) {
	ctx, cancel := context.WithTimeout(ctx, apiTimeout)
	defer cancel()

	serviceURL := cfg.ServiceURL
	if serviceURL == "" {
		serviceURL = DefaultServiceURL
	}

	// Build URL: /search/v1/:owner/:repo?q=...&branch=...&limit=...
	u, err := url.Parse(serviceURL)
	if err != nil {
		return nil, fmt.Errorf("parsing service URL: %w", err)
	}
	u.Path = fmt.Sprintf("/search/v1/%s/%s", url.PathEscape(cfg.Owner), url.PathEscape(cfg.Repo))

	q := u.Query()
	q.Set("q", cfg.Query)
	if cfg.Branch != "" {
		q.Set("branch", cfg.Branch)
	}
	if cfg.Limit > 0 {
		q.Set("limit", strconv.Itoa(cfg.Limit))
	}
	u.RawQuery = q.Encode()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return nil, fmt.Errorf("creating request: %w", err)
	}
	req.Header.Set("Authorization", "token "+cfg.GitHubToken)
	req.Header.Set("User-Agent", "entire-cli")

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("calling search service: %w", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return nil, fmt.Errorf("reading response: %w", err)
	}

	if resp.StatusCode != http.StatusOK {
		var errResp struct {
			Error string `json:"error"`
		}
		if json.Unmarshal(body, &errResp) == nil && errResp.Error != "" {
			return nil, fmt.Errorf("search service error (%d): %s", resp.StatusCode, errResp.Error)
		}
		return nil, fmt.Errorf("search service returned %d: %s", resp.StatusCode, string(body))
	}

	var result Response
	if err := json.Unmarshal(body, &result); err != nil {
		return nil, fmt.Errorf("parsing response: %w", err)
	}

	return &result, nil
}

import { Hono } from "hono"
import { getCookie } from "hono/cookie"
import { cors } from "hono/cors"
import { logger } from "hono/logger"

import { sha256Hex, API_TOKEN_PREFIX } from "../lib/crypto"
import { createApiTokensNamespace } from "../lib/planetscale/api-tokens"
import { getUserByGithubId } from "../lib/planetscale/search-queries"
import { SearchService } from "../lib/search-service"
import type { SearchResponse } from "../lib/search-service"
import { getSession } from "../lib/session"
import { getKysely } from "./db"
import { validateEnv, isLocalDev, type Env } from "./env"
import { getAuthenticatedUser, AuthError, NotFoundError } from "./github-auth"

const app = new Hono<{ Bindings: Env }>()

// Global middleware
app.use("*", logger())
app.use("*", (c, next) => {
  validateEnv(c.env)
  return next()
})
app.use("*", (c, next) => {
  const origins = c.env.ALLOWED_ORIGINS.split(",").map((s) => s.trim())
  return cors({
    origin: origins,
    credentials: true,
  })(c, next)
})

// Health check
app.get("/search/v1/health", (c) => {
  return c.json({
    status: "ok",
    service: "entire-search",
    environment: c.env.ENVIRONMENT,
    timestamp: Date.now(),
  })
})

// ─── Auth helper: session cookie → Entire API token → GitHub token ────────────

async function resolveUserId(c: any): Promise<{ userId: string; login?: string } | Response> {
  // 1. Try session cookie (frontend)
  const sessionToken = getCookie(c, "session")
  if (sessionToken) {
    const session = await getSession(c.env.ENTIRE_CACHE, sessionToken)
    if (session) {
      return { userId: session.userId }
    }
  }

  // 2. Extract Bearer/token from Authorization header
  const authHeader = c.req.header("Authorization")
  if (!authHeader) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const token = authHeader.replace(/^(token|Bearer)\s+/i, "")
  if (!token) {
    return c.json({ error: "Invalid authorization header" }, 401)
  }

  // 3. Try Entire API token (ent_*) — used by CLI
  if (token.startsWith(API_TOKEN_PREFIX)) {
    const hash = await sha256Hex(token)
    const db = getKysely(c.env)
    const apiTokens = createApiTokensNamespace(db)
    const lookup = await apiTokens.findByTokenHash(hash)

    if (!lookup) {
      return c.json({ error: "Invalid or expired token" }, 401)
    }

    if (new Date(lookup.expires_at) < new Date()) {
      return c.json({ error: "Token expired" }, 401)
    }
    // Fire-and-forget: update last_used_at
    try {
      c.executionCtx.waitUntil(apiTokens.updateLastUsedAt(lookup.id))
    } catch {
      void apiTokens.updateLastUsedAt(lookup.id)
    }

    return { userId: lookup.user_id }
  }

  // 4. Fall back to GitHub token
  const ghUser = await getAuthenticatedUser(token)
  const db = getKysely(c.env)
  const user = await getUserByGithubId(db, ghUser.id)

  if (!user) {
    return c.json({ error: "User not found in Entire" }, 404)
  }

  return { userId: user.id, login: ghUser.login }
}

// ─── Unified search ───────────────────────────────────────────────────────────
app.get("/search/v1/search", async (c) => {
  const q = c.req.query("q")
  const typesParam = c.req.query("types")
  const repo = c.req.query("repo")
  const author = c.req.query("author")
  const dateParam = c.req.query("date")
  const pageParam = c.req.query("page")
  const limitParam = c.req.query("limit")

  if (!q) {
    return c.json({ error: "Query parameter 'q' is required" }, 400)
  }

  const trimmedQ = q.trim()
  if (!trimmedQ) {
    return c.json({ error: "Query must contain non-whitespace characters" }, 400)
  }

  const MAX_QUERY_LENGTH = 500
  if (trimmedQ.length > MAX_QUERY_LENGTH) {
    return c.json({ error: `Query too long (max ${MAX_QUERY_LENGTH} characters)` }, 400)
  }

  const validDates = ["week", "month"]
  if (dateParam && !validDates.includes(dateParam)) {
    return c.json(
      { error: `Invalid date value '${dateParam}'. Must be one of: ${validDates.join(", ")}` },
      400,
    )
  }

  const parsedTypes = typesParam
    ? (typesParam.split(",").filter((t) => ["repos", "checkpoints"].includes(t)) as (
        | "repos"
        | "checkpoints"
      )[])
    : undefined
  const types = parsedTypes?.length ? parsedTypes : undefined

  const limitRaw = limitParam ? parseInt(limitParam, 10) : 20
  const limit = Math.max(1, Math.min(Number.isNaN(limitRaw) ? 20 : limitRaw, 200))
  const perType = { repos: Math.min(limit, 20), checkpoints: limit }

  try {
    const authResult = await resolveUserId(c)
    if (authResult instanceof Response) return authResult
    const { userId, login } = authResult

    const db = getKysely(c.env)

    console.log(
      `[search] request`,
      JSON.stringify({
        user: login ?? userId,
        queryLength: trimmedQ.length,
        limit,
        types: types ?? ["repos", "checkpoints"],
      }),
    )

    const semanticEnabled = !!(
      c.env.TURBOPUFFER_API_KEY &&
      c.env.OPENAI_API_KEY &&
      c.env.SEARCH_ENABLED_ORGS
    )
    const enabledOrgs = c.env.SEARCH_ENABLED_ORGS
      ? new Set(c.env.SEARCH_ENABLED_ORGS.split(",").map((s) => s.trim().toLowerCase()))
      : undefined

    const svc = new SearchService(
      db,
      c.env.TURBOPUFFER_API_KEY,
      c.env.OPENAI_API_KEY,
      semanticEnabled,
      c.env.SEARCH_CACHE,
      enabledOrgs,
      c.env.COHERE_API_KEY,
    )

    const result: SearchResponse = await svc.search(userId, {
      q: trimmedQ,
      types,
      repo,
      author,
      date: dateParam as "week" | "month" | undefined,
      page: (() => {
        const p = pageParam ? parseInt(pageParam, 10) : 1
        return Number.isNaN(p) ? 1 : p
      })(),
      limit,
      perType,
    })

    return c.json(result)
  } catch (err) {
    if (err instanceof AuthError) {
      return c.json({ error: "Invalid or expired GitHub token" }, 401)
    }
    if (err instanceof NotFoundError) {
      return c.json({ error: (err as Error).message }, 404)
    }
    console.error(`[search] error:`, err)
    const showMessage = isLocalDev(c.env)
    return c.json(
      {
        error: "Search failed",
        message: showMessage ? (err as Error).message : undefined,
      },
      500,
    )
  }
})

// 404 handler
app.notFound((c) => c.json({ error: "Not found" }, 404))

// Error handler
app.onError((err, c) => {
  console.error("Unhandled error:", err)
  const showMessage = isLocalDev(c.env)
  return c.json(
    {
      error: "Internal server error",
      message: showMessage ? err.message : undefined,
    },
    500,
  )
})

export default {
  fetch: app.fetch,
}

// Shared types for search — used by both the API route (routes/search.ts)
// and the standalone search worker (search-worker/).

export type SearchMatchType = "keyword" | "semantic" | "both"

export interface SearchMeta {
  matchType: SearchMatchType
  score: number
  snippet?: string
}

export interface RepoResult {
  id: string
  githubRepoId: number
  org: string
  name: string
  fullName: string
  description: string | null
  checkpointCount: number
}

export interface CheckpointResult {
  id: string
  prompt: string
  commitMessage: string | null
  commitSha: string | null
  branch: string
  org: string
  repo: string
  author: string
  authorUsername: string | null
  createdAt: string
  filesTouched: string[]
}

export type SearchResult =
  | { type: "repo"; data: RepoResult; searchMeta: SearchMeta }
  | { type: "checkpoint"; data: CheckpointResult; searchMeta: SearchMeta }

export interface SearchTiming {
  total_ms: number
  keyword_ms: number | null
  embedding_ms: number | null
  vector_ms: number | null
  rerank_ms: number | null
}

export interface SearchResponse {
  results: SearchResult[]
  total: number
  page: number
  timing: SearchTiming
  reranked?: boolean
}

export interface SearchParams {
  q: string
  types?: ("repos" | "checkpoints")[]
  repo?: string
  author?: string
  date?: "week" | "month"
  page: number
  limit: number
  perType: { repos: number; checkpoints: number }
}

